import sys
import os
import subprocess
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor

def process_job(job_element):
    command = job_element.find('command').text
    output_path = job_element.find('output').text
    try:
        with open(output_path, 'w') as f:
            subprocess.run(command, shell=True, check=True, stdout=f, stderr=f)
    except subprocess.CalledProcessError as e:
        with open(output_path, 'w') as f:
            f.write(f"Command failed with exit code {e.returncode}\n")
            f.write(f"Error details: {e}\n")

def main():
    xml_path = sys.stdin.readline().strip()
    if not xml_path:
        sys.exit(1)

    tree = ET.parse(xml_path)
    root = tree.getroot()
    max_parallel = int(root.attrib['max_parallel'])
    jobs = root.findall('job')

    with ThreadPoolExecutor(max_parallel) as executor:
        futures = []
        batch = []
        for job in jobs:
            batch.append(job)
            if len(batch) >= max_parallel:
                futures.extend(executor.submit(process_job, job) for job in batch)
                while futures:
                    done, _ = executor.drain()
                    for future in done:
                        try:
                            future.result()
                        except Exception as e:
                            print(f"Error processing job: {e}", file=sys.stderr)
                batch = []
        if batch:
            futures.extend(executor.submit(process_job, job) for job in batch)
            while futures:
                done, _ = executor.drain()
                for future in done:
                    try:
                        future.result()
                    except Exception as e:
                        print(f"Error processing job: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()
